\section{Introduction}

\subsection{The problem}
Let $\Omega$ be a finite alphabet and let $X=(X_1,\dots,X_n)$ be independent
random variables with $X_i\sim\mu_i$ on $\Omega$. For which functions
$f:\Omega^n\to\RR$ is $f(X)$ tightly clustered about a central value, and on what
scale?

The classical answer, the bounded differences inequality, states that if changing
a single coordinate changes $f$ by at most $c_i$, then
$\PP(|f-\EE f|\ge t)\le 2\exp(-2t^2/\sum_i c_i^2)$: the scale is
$(\sum_i c_i^2)^{1/2}$, typically $\sqrt n$. For many combinatorial functionals
this is the wrong scale by a polynomial factor. The canonical example is the
length $L_n$ of the longest increasing subsequence of a uniform random word of
length $n$: here $L_n\asymp\sqrt n$, so a bound on fluctuations of order $\sqrt n$
carries no information.

Talagrand's convex distance inequality resolves this by replacing the fixed
per-coordinate Lipschitz budget with a geometric quantity---the Euclidean
distance from the origin to a convex hull of disagreement patterns---whose
duality theory permits the Lipschitz \emph{witness} to be chosen anew at each
point of the space.

\subsection{Contributions}
We present: a proof of the convex distance inequality for arbitrary finite
product measures (Theorem~\ref{thm:main}); a clean separation of the analytic
core, namely a weighted H\"older inequality (Lemma~\ref{lem:holder}) and the
interpolation lemma with the optimal constant (Theorem~\ref{thm:interp},
Proposition~\ref{prop:opt}); the minimax identity $\dT=\sup_w d_w$
(Theorem~\ref{thm:minimax}); exact convex distances to singletons and subcubes
(Theorems~\ref{thm:singleton},~\ref{thm:cyl}); concentration for Lipschitz and
certifiable functionals (Theorems~\ref{thm:lip}--\ref{thm:lis}); and algorithms
for computing the convex distance and exercising the bounds numerically
(Section~\ref{sec:alg}).

Throughout we work with the \emph{square} $\dT^2$, the quantity carried by the
induction, and represent hull points by explicit finite convex combinations
rather than an abstract convex-hull operator; this makes the geometric step of
the induction elementary.

\section{Definitions}

Throughout, $\Omega$ is a finite alphabet, $n\in\mathbb N$, and the ambient space
is $\Omega^n$.

\begin{definition}[Hamming indicator]
For $u,v\in\Omega$ set $h(u,v)=0$ if $u=v$ and $h(u,v)=1$ otherwise. For
$x,y\in\Omega^n$ the \emph{disagreement vector} is
$U(x,y)=(h(x_1,y_1),\dots,h(x_n,y_n))\in\{0,1\}^n$.
\end{definition}

\begin{definition}[Squared Euclidean norm]
For $v\in\RR^n$, $\sqn(v)=\sum_{i=1}^n v_i^2$.
\end{definition}

\begin{definition}[Hull representation]\label{def:rep}
Let $A\subseteq\Omega^n$ be finite and $x\in\Omega^n$. A vector $v\in\RR^n$
\emph{represents} $A$ at $x$ if there exist $k\in\mathbb N$, weights
$\alpha_1,\dots,\alpha_k\ge0$ with $\sum_j\alpha_j=1$, and points
$y^{(1)},\dots,y^{(k)}\in A$ such that
\[
  v_i=\sum_{j=1}^k \alpha_j\, h\big(x_i,y^{(j)}_i\big),\qquad 1\le i\le n.
\]
Equivalently, $v$ represents $A$ at $x$ if and only if there is a weight
$\alpha:A\to[0,\infty)$ with $\sum_{y\in A}\alpha_y=1$ and
$v_i=\sum_{y\in A}\alpha_y h(x_i,y_i)$: one passes from an indexed list to a
weight by aggregating duplicates, and back by enumerating the support. Every
representing vector satisfies $0\le v_i\le1$.
\end{definition}

\begin{definition}[Convex distance]
For nonempty finite $A\subseteq\Omega^n$ and $x\in\Omega^n$,
\[
  \dT^2(A,x)=\inf\{\sqn(v):v\text{ represents }A\text{ at }x\}.
\]
\end{definition}

\begin{definition}[Weighted Hamming distance]
For $w\in[0,\infty)^n$, $d_w(A,x)=\min_{y\in A}\sum_{i=1}^n w_i h(x_i,y_i)$.
A weight $w$ is \emph{admissible} if $w\ge0$ and $\sum_i w_i^2\le1$.
\end{definition}

\begin{definition}[Product measure]
Given probability weights $p_i:\Omega\to[0,\infty)$, $\sum_a p_i(a)=1$, put
$\wt(x)=\prod_i p_i(x_i)$, $\PP(S)=\sum_{x\in S}\wt(x)$, and
\[
  E(A)=\sum_{x\in\Omega^n}\wt(x)\,e^{\dT^2(A,x)/4}=\EE\big[e^{\dT^2(A,X)/4}\big].
\]
\end{definition}

Elementary properties: $\dT^2(A,x)\ge0$; $\dT^2(A,x)=0$ for $x\in A$;
$\dT^2(A,x)\le n$; and $\dT^2$ is antitone in $A$.

\begin{lemma}[Easy half of duality]\label{lem:easy}
For every admissible $w$, nonempty $A$ and every $x$, $d_w(A,x)^2\le\dT^2(A,x)$.
\end{lemma}

\begin{proof}
Let $v$ represent $A$ at $x$ with weights $\alpha_y$. Then
$\sum_i w_iv_i=\sum_{y}\alpha_y\sum_i w_ih(x_i,y_i)\ge d_w(A,x)$, while
Cauchy--Schwarz gives $\sum_i w_iv_i\le\|w\|_2\sqn(v)^{1/2}\le\sqn(v)^{1/2}$.
Hence $\sqn(v)\ge d_w(A,x)^2$ for every representing $v$; take the infimum.
\end{proof}

\section{The analytic core}

\subsection{Weighted H\"older inequality}

\begin{lemma}[Weighted H\"older]\label{lem:holder}
Let $S$ be finite, $q,f,g:S\to[0,\infty)$, $\lambda\in[0,1]$, and suppose
$F=\sum_i q_if_i>0$ and $G=\sum_i q_ig_i>0$. Then
\[
  \sum_{i\in S} q_i\,f_i^{\lambda}g_i^{1-\lambda}\ \le\ F^{\lambda}G^{1-\lambda}.
\]
\end{lemma}

\begin{proof}
Write $f_i^\lambda g_i^{1-\lambda}=F^\lambda G^{1-\lambda}(f_i/F)^\lambda
(g_i/G)^{1-\lambda}$ and apply the two-point weighted AM--GM inequality
$s^\lambda t^{1-\lambda}\le\lambda s+(1-\lambda)t$. Multiplying by $q_i\ge0$,
summing, and using $\sum_i q_if_i/F=1=\sum_i q_ig_i/G$ collapses the right-hand
side to $F^\lambda G^{1-\lambda}$.
\end{proof}

\subsection{Explicit Taylor bounds}

\begin{lemma}\label{lem:taylor}
For $0\le t\le1$:
\[
 e^{t}\le 1+t+\tfrac34t^2,\qquad
 e^{-t}\le 1-t+\tfrac{t^2}{2}+\tfrac29t^3,
\]
\[
 e^{t}\le 1+t+\tfrac{t^2}{2}+\tfrac{t^3}{6}+\tfrac{5}{96}t^4,\qquad
 e^{-t}\le 1-t+\tfrac{t^2}{2}-\tfrac{t^3}{6}+\tfrac{5}{96}t^4 .
\]
\end{lemma}

\begin{proof}
All four follow from the truncated-series estimate
$\big|e^{t}-\sum_{m<N}t^m/m!\big|\le |t|^{N}(N+1)/(N!\,N)$ for $|t|\le1$,
together with the sharper one-sided bound available for $t\ge0$; evaluating the
remainder constants at $N=2,3,4$ gives $\tfrac34$, $\tfrac29$ and $\tfrac5{96}$.
\end{proof}

\subsection{The interpolation lemma}

\begin{theorem}[Interpolation lemma]\label{thm:interp}
For every $r\in[0,1]$ there exists $\lambda\in[0,1]$ with
\[
  e^{(1-\lambda)^2/4}\,r^{-\lambda}\ \le\ 2-r .
\]
\end{theorem}

\begin{proof}
\emph{Regime 1: $r<e^{-1/2}$.} Take $\lambda=0$; the claim is $e^{1/4}\le2-r$.
By Lemma~\ref{lem:taylor} at $t=\tfrac12$, $e^{-1/2}\le0.6528$, so $2-r>1.3472$,
while $e^{1/4}\le1+\tfrac14+\tfrac34\cdot\tfrac1{16}=1.2969$.

\emph{Regime 2: $r\ge e^{-1/2}$.} Write $u=-\log r\in[0,\tfrac12]$ and take
$\lambda=1+2\log r=1-2u\in[0,1]$. Then $(1-\lambda)^2/4=u^2$ and
$r^{-\lambda}=e^{u\lambda}=e^{u-2u^2}$, so the left-hand side equals
$e^{u-u^2}$; apply Theorem~\ref{thm:scalar}.
\end{proof}

\begin{theorem}[Scalar heart]\label{thm:scalar}
For $0\le u\le\tfrac12$, $\ e^{u-u^2}\le 2-e^{-u}$.
\end{theorem}

\begin{proof}
Set $t=u-u^2\in[0,\tfrac14]$. By Lemma~\ref{lem:taylor} it suffices to prove the
polynomial inequality
\[
 \Big(1+t+\tfrac{t^2}{2}+\tfrac{t^3}{6}+\tfrac{5}{96}t^4\Big)
 +\Big(1-u+\tfrac{u^2}{2}-\tfrac{u^3}{6}+\tfrac{5}{96}u^4\Big)\le 2,
 \qquad t=u-u^2,
\]
on $[0,\tfrac12]$. Substituting $t=u-u^2$, the constant, linear and quadratic
terms cancel identically; the cubic terms combine to $-u^3$, and the remaining
quartic and higher terms are dominated by $u^3$ on $[0,\tfrac12]$.
\end{proof}

\begin{proposition}[Optimality of $1/4$]\label{prop:opt}
Let $c>0$ and suppose that for every $r\in(0,1)$ there is $\lambda\in[0,1]$ with
$e^{c(1-\lambda)^2}r^{-\lambda}\le 2-r$. Then $c\le\tfrac14$.
\end{proposition}

\begin{proof}
Write $r=e^{-u}$ with $u>0$ small and $\lambda=1-2s$, $s\in[0,\tfrac12]$. The
logarithm of the left-hand side is $4cs^2+u(1-2s)$, minimised at $s=u/(4c)$ with
value $u-u^2/(4c)$, while $\log(2-e^{-u})=u-u^2+u^3+O(u^4)$. The hypothesis then
requires $\big(1-\tfrac1{4c}\big)u^2\le u^3+O(u^4)$ for all small $u>0$, forcing
$c\le\tfrac14$.
\end{proof}

Thus the two curves of Theorem~\ref{thm:scalar} agree to second order at $u=0$
and separate only at order $u^3$, with gap $u^3+O(u^4)$; the whole strength of
the concentration inequality rests on this third-order tangency.

\section{The convex distance inequality}

\begin{theorem}[Convex distance inequality]\label{thm:main}
Let $p_1,\dots,p_n$ be probability weights on the finite alphabet $\Omega$ and
let $\PP$ be the associated product measure on $\Omega^n$. Then for every
$A\subseteq\Omega^n$,
\[
  \EE\big[e^{\dT^2(A,X)/4}\big]\cdot\PP(A)\ \le\ 1 .
\]
In particular this holds in the i.i.d.\ case.
\end{theorem}

Write a point of $\Omega^{n+1}$ as $(a,y)$, $a\in\Omega$, $y\in\Omega^n$.

\begin{definition}
For $A\subseteq\Omega^{n+1}$ and $a\in\Omega$, the \emph{section} is
$A_a=\{y:(a,y)\in A\}$ and the \emph{projection} is
$\Pi A=\{y:\exists b,\ (b,y)\in A\}$.
\end{definition}

\begin{lemma}[Mixing step]\label{lem:mix}
Let $A\subseteq\Omega^{n+1}$, $a\in\Omega$, $y\in\Omega^n$ and $\lambda\in[0,1]$.
Assume $\Pi A\neq\emptyset$, and if $\lambda\neq0$ assume also
$A_a\neq\emptyset$. Then
\[
  \dT^2\big(A,(a,y)\big)\ \le\ (1-\lambda)^2+\lambda\,\dT^2(A_a,y)
  +(1-\lambda)\,\dT^2(\Pi A,y).
\]
\end{lemma}

\begin{proof}
Fix $\varepsilon>0$ and pick weights on $A_a$ and on $\Pi A$ whose induced
vectors $v^{(1)},v^{(2)}$ are within $\varepsilon$ of optimal. Lift them to
weights on $A$: a point $y'\in A_a$ lifts to $(a,y')\in A$, agreeing with $(a,y)$
in the new coordinate; a point $y'\in\Pi A$ lifts to some $(b,y')\in A$, possibly
disagreeing there. Mixing with weights $\lambda,1-\lambda$ yields a
representation $v$ of $A$ at $(a,y)$ whose new coordinate is at most $1-\lambda$,
so by convexity of $s\mapsto s^2$,
\[
 \sqn(v)\le(1-\lambda)^2+\sum_{i\le n}\big(\lambda v^{(1)}_i+(1-\lambda)v^{(2)}_i\big)^2
 \le(1-\lambda)^2+\lambda\sqn(v^{(1)})+(1-\lambda)\sqn(v^{(2)}).
\]
Let $\varepsilon\to0$.
\end{proof}

The structural point is that the new coordinate contributes $(1-\lambda)^2$
\emph{quadratically} while the inductive terms appear linearly.

\begin{proof}[Proof of Theorem~\ref{thm:main}]
Induction on $n$. For $n=0$ the space is a single point: either $A=\emptyset$ and
the product vanishes, or $\PP(A)=1$ and $\dT^2=0$.

Assume the result in dimension $n$ and let $\emptyset\neq A\subseteq\Omega^{n+1}$.
Put $B=\Pi A$, $q=\PP_n(B)>0$, $s_a=\PP_n(A_a)\le q$ and $r_a=s_a/q\in[0,1]$;
note $\PP(A)=\sum_a p_1(a)s_a$. Fix $a$ and let $\lambda=\lambda(a)\in[0,1]$ be
given by Theorem~\ref{thm:interp} for $r=r_a$. Exponentiating
Lemma~\ref{lem:mix},
\[
 e^{\dT^2(A,(a,y))/4}\le e^{(1-\lambda)^2/4}
 \big(e^{\dT^2(A_a,y)/4}\big)^{\lambda}\big(e^{\dT^2(B,y)/4}\big)^{1-\lambda}.
\]
Multiplying by $\wt_n(y)$, summing over $y$, and applying
Lemma~\ref{lem:holder},
\[
 \sum_y \wt_n(y)e^{\dT^2(A,(a,y))/4}\le
 e^{(1-\lambda)^2/4}E_n(A_a)^{\lambda}E_n(B)^{1-\lambda}
 \le \frac1q\,e^{(1-\lambda)^2/4}r_a^{-\lambda}\le\frac{2-r_a}{q},
\]
using the induction hypothesis $E_n(A_a)\le1/s_a$, $E_n(B)\le1/q$ (the case
$s_a=0$ being covered by $\lambda=0$) and then Theorem~\ref{thm:interp}. Summing
over $a$ with weights $p_1(a)$ and setting $\theta=\PP(A)/q=\sum_a p_1(a)r_a$,
\[
 E_{n+1}(A)\PP(A)\le\frac{2-\theta}{q}\cdot\theta q=\theta(2-\theta)=1-(1-\theta)^2\le1 .
\]
Independence is used only through $\wt(a,y)=p_1(a)\wt_n(y)$; the $p_i$ need not
be equal.
\end{proof}

\section{Geometry of the convex distance}

\begin{lemma}[Attainment]\label{lem:att}
For nonempty finite $A$ and any $x$, the infimum defining $\dT^2(A,x)$ is
attained at some representing $v^\star$.
\end{lemma}

\begin{proof}
The representing set is the image of the compact simplex
$\{\alpha\in[0,1]^A:\sum_y\alpha_y=1\}$ under a continuous linear map, hence
compact; $\sqn$ attains its minimum there.
\end{proof}

\begin{lemma}[Variational inequality]\label{lem:var}
If $v^\star$ minimises $\sqn$ over representing vectors, then
$\langle v^\star,u\rangle\ge\sqn(v^\star)$ for every representing $u$.
\end{lemma}

\begin{proof}
The representing set is convex, so $v_\tau=(1-\tau)v^\star+\tau u$ is
representing for $\tau\in[0,1]$ and $\sqn(v_\tau)\ge\sqn(v^\star)$, i.e.
$2\tau\langle v^\star,u-v^\star\rangle+\tau^2\sqn(u-v^\star)\ge0$. Divide by
$\tau$ and let $\tau\downarrow0$.
\end{proof}

\begin{theorem}[Hard half of duality]\label{thm:hard}
For nonempty $A$ and any $x$ there is an admissible $w$ with
$\dT^2(A,x)\le d_w(A,x)^2$.
\end{theorem}

\begin{proof}
If $\dT^2(A,x)=0$ take $w=0$. Otherwise let $v^\star$ be as in
Lemma~\ref{lem:att} and set $w=v^\star/\|v^\star\|_2$, which is nonnegative with
$\|w\|_2=1$. For $y\in A$, Lemma~\ref{lem:var} applied to $u=U(x,y)$ gives
$\sum_i w_ih(x_i,y_i)\ge\sqn(v^\star)/\|v^\star\|_2=\|v^\star\|_2=\dT(A,x)$.
Minimise over $y$.
\end{proof}

\begin{theorem}[Minimax identity]\label{thm:minimax}
For nonempty $A$ and any $x$,
\[
  \dT(A,x)=\sup\Big\{\,d_w(A,x)\ :\ w\ge0,\ \textstyle\sum_i w_i^2\le1\,\Big\},
\]
and the supremum is attained.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:easy} gives ``$\ge$''; Theorem~\ref{thm:hard} gives ``$\le$''.
\end{proof}

The minimax identity is the operational form of the theory: to certify that $x$
is far from $A$, exhibit any admissible $w$---chosen freely as a function of
$x$---under which every point of $A$ is far from $x$.

\begin{theorem}[Singletons]\label{thm:singleton}
For $y,x\in\Omega^n$, $\dT^2(\{y\},x)=\#\{i:x_i\neq y_i\}$. In particular, if
$x_i\neq y_i$ for all $i$ then $\dT^2(\{y\},x)=n$.
\end{theorem}

\begin{proof}
The only representing vector is $U(x,y)$, whose entries are $0/1$.
\end{proof}

\begin{definition}
For $B\subseteq\{1,\dots,n\}$ and $c\in\Omega^n$, the \emph{cylinder} (subcube)
is $\Cyl(B,c)=\{y: y_i=c_i \text{ for all } i\in B\}$.
\end{definition}

\begin{theorem}[Exact convex distance to a subcube]\label{thm:cyl}
$\dT^2(\Cyl(B,c),x)=\#\{i\in B: x_i\neq c_i\}$ for all $B,c,x$.
\end{theorem}

\begin{proof}
Upper bound: the patched point $y$ with $y_i=c_i$ on $B$ and $y_i=x_i$ off $B$
lies in the cylinder, and $\sqn(U(x,y))=\#\{i\in B:x_i\neq c_i\}$. Lower bound:
every point of the cylinder disagrees with $x$ on $D=\{i\in B: x_i\neq c_i\}$, so
every representing $v$ has $v_i=1$ for $i\in D$ and $\sqn(v)\ge|D|$.
\end{proof}

\section{Concentration inequalities}

\begin{theorem}[Deviation bound]\label{thm:dev}
If $\dT^2(A,x)\ge t$ for all $x\in S$, then $\PP(A)\PP(S)\le e^{-t/4}$.
\end{theorem}

\begin{proof}
For $x\in S$, $\wt(x)\le e^{-t/4}\wt(x)e^{\dT^2(A,x)/4}$; sum over $S$, extend
to $\Omega^n$, and apply Theorem~\ref{thm:main}.
\end{proof}

\begin{theorem}[Isoperimetric form]\label{thm:iso}
If $\PP(A)\ge\tfrac12$ and $\dT^2(A,\cdot)\ge t$ on $S$, then
$\PP(S)\le 2e^{-t/4}$.
\end{theorem}

\begin{theorem}[Weighted Hamming form]\label{thm:ham}
Let $w$ be admissible, $A\neq\emptyset$, $t\ge0$, and $d_w(A,x)\ge t$ for all
$x\in S$. Then $\PP(A)\PP(S)\le e^{-t^2/4}$.
\end{theorem}

\begin{proof}
Combine Lemma~\ref{lem:easy} with Theorem~\ref{thm:dev} at level $t^2$.
\end{proof}

\begin{theorem}[Concentration of $1$-Lipschitz functionals]\label{thm:lip}
Let $w$ be admissible and let $f:\Omega^n\to\RR$ satisfy
$f(x)\le f(y)+\sum_i w_ih(x_i,y_i)$ for all $x,y$. If $f\le m$ on a nonempty $A$
and $f\ge m+t$ on $S$ with $t\ge0$, then $\PP(A)\PP(S)\le e^{-t^2/4}$. If
moreover $\PP(A)\ge\tfrac12$, then $\PP(f\ge m+t)\le 2e^{-t^2/4}$.
\end{theorem}

\begin{proof}
For $x\in S$, $y\in A$: $\sum_i w_ih(x_i,y_i)\ge f(x)-f(y)\ge t$, so
$d_w(A,x)\ge t$; apply Theorem~\ref{thm:ham}.
\end{proof}

\begin{example}
On $\{0,1\}^n$ with independent coins of arbitrary biases $\theta_i\in[0,1]$, let
$f(x)=n^{-1/2}\#\{i:x_i=1\}$ and $w_i=n^{-1/2}$ (admissible). Theorem~\ref{thm:lip}
yields sub-Gaussian tails $\PP(A)\PP(S)\le e^{-t^2/4}$ for the corresponding
level sets.
\end{example}

\subsection{Certifiable functionals}

\begin{definition}[Certificate]
A point $x$ \emph{admits a certificate of size $K$ at level $m$} for
$f:\Omega^n\to\RR$ if there is $J\subseteq\{1,\dots,n\}$ with $|J|\le K$ such
that every $y$ with $y_i=x_i$ for all $i\in J$ satisfies $f(y)\ge m$.
\end{definition}

\begin{theorem}[Certifiable concentration]\label{thm:cert}
Let $f$ be $1$-Lipschitz for the plain Hamming metric, $K>0$, $b\le m$. Suppose
$f\le b$ on a nonempty $A$ and every $x\in S$ admits a certificate of size at
most $K$ at level $m$. Then
\[
 \PP(A)\,\PP(S)\ \le\ \exp\!\Big(-\frac{(m-b)^2}{4K}\Big).
\]
\end{theorem}

\begin{proof}
Fix $x\in S$ with certificate $J$ and set $w_i=|J|^{-1/2}\one{i\in J}$, an
admissible weight. Let $y\in A$ and let $y'$ agree with $x$ on $J$ and with $y$
off $J$. The certificate gives $f(y')\ge m$, while $1$-Lipschitzness gives
$f(y')\le f(y)+\#\{i\in J: y_i\neq x_i\}\le b+\#\{i\in J:y_i\neq x_i\}$. Hence
$\#\{i\in J:x_i\neq y_i\}\ge m-b$ and
$\sum_i w_ih(x_i,y_i)\ge(m-b)/\sqrt K$, so $d_w(A,x)\ge(m-b)/\sqrt K$; apply
Theorem~\ref{thm:ham}. Note that $w$ depends on $x$, which is legitimate by
Theorem~\ref{thm:minimax}.
\end{proof}

\begin{corollary}[Counting ones at the certificate scale]\label{cor:ones}
On $\{0,1\}^n$ with independent coins of arbitrary biases, let
$N(x)=\#\{i:x_i=1\}$ and $0<b\le m$. If $N\le b$ on a nonempty $A$ and $N\ge m$
on $S$, then $\PP(A)\PP(S)\le\exp\big(-(m-b)^2/(4\lceil m\rceil)\big)$.
\end{corollary}

\begin{proof}
$N$ is $1$-Lipschitz, and any $\lceil m\rceil$ positions carrying ones certify
$N\ge m$. Apply Theorem~\ref{thm:cert} with $K=\lceil m\rceil$.
\end{proof}

For $m=o(n)$ this is far stronger than any bound with $n$ in the denominator.

\subsection{Longest increasing subsequence}

Let $\Omega$ be linearly ordered and, for $x\in\Omega^n$, let $L(x)$ be the
maximal size of a set $S\subseteq\{1,\dots,n\}$ with $x_i\le x_j$ whenever
$i\le j$ in $S$.

\begin{lemma}\label{lem:lislip}
$L(z)\le L(y)+\#\{i:z_i\neq y_i\}$.
\end{lemma}

\begin{proof}
Delete from an optimal increasing set for $z$ the indices where $z$ and $y$
differ; the remainder is increasing for $y$.
\end{proof}

\begin{lemma}\label{lem:liscert}
If $L(x)\ge\ell$ then $x$ admits a certificate of size $\lceil\ell\rceil$ at
level $\ell$: any witnessing increasing subsequence of that length, since any
word agreeing with $x$ there contains the same increasing subsequence.
\end{lemma}

\begin{theorem}[Concentration of the longest increasing subsequence]\label{thm:lis}
For any product measure on words of length $n$, any $0<b\le\ell$, and sets $A,S$
with $L\le b$ on a nonempty $A$ and $L\ge\ell$ on $S$,
\[
 \PP(A)\,\PP(S)\ \le\ \exp\!\Big(-\frac{(\ell-b)^2}{4\lceil\ell\rceil}\Big).
\]
\end{theorem}

Since $L\asymp\sqrt n$ in the uniform model, the deviation scale is
$\sqrt\ell\asymp n^{1/4}$, matching the true order of fluctuations up to
constants, whereas bounded differences gives only $\sqrt n$.

\section{Algorithms}\label{sec:alg}

\subsection{Computing the convex distance}
$\dT^2(A,x)$ is the value of the quadratic program
$\min_{\alpha\in\Delta(A)}\|M_x\alpha\|_2^2$ with $(M_x)_{i,y}=h(x_i,y_i)$: the
minimum-norm point of a polytope. Frank--Wolfe with exact line search has
iteration cost $O(n|A|)$ and $O(1/k)$ error decay; the pairwise (away-step)
variant converges linearly on a polytope. A dual certificate is free: with
$w=v/\|v\|_2$, the gap $\|v\|_2-\min_{y\in A}\langle w,U(x,y)\rangle$ is
nonnegative and vanishes exactly at the optimum by Theorem~\ref{thm:minimax},
giving a rigorous a posteriori bracket for $\dT(A,x)$.

\subsection{Verifying the exponential moment bound}
For small $|\Omega|$ and $n$ one enumerates $\Omega^n$, computes $\dT^2(A,x)$ for
each $x$ and evaluates $E(A)\PP(A)$; the value is always $\le1$ and typically
close to $1$, reflecting the tightness of the averaging step
$\theta(2-\theta)\le1$.

\subsection{Evaluating the interpolation profile}
For $r$ on a grid in $[0,1]$, $\Phi(r)=\min_{\lambda\in[0,1]}
e^{(1-\lambda)^2/4}r^{-\lambda}$ is computed in closed form, the minimiser being
the projection of $1+2\log r$ onto $[0,1]$; the gap $2-r-\Phi(r)$ is nonnegative
and vanishes to third order as $r\to1$.

\section{Discussion}

\textbf{Why the convex distance.} The hull description is what the induction can
process---the mixing step is a statement about convex combinations, and its
quadratic-versus-linear asymmetry is exactly what the interpolation lemma
exploits. The dual description is what applications need: it converts the
inequality into a recipe (find a witness weight vector) and lets that recipe be
point-dependent.

\textbf{Comparison with bounded differences.} McDiarmid's inequality corresponds
to fixing a single admissible $w$ for all $x$. Talagrand's theorem allows a
supremum over $w$ inside the probability at the cost of only a constant in the
exponent. Whenever the reason $f$ is large varies from point to point---as with
subsequences, cliques, tours or covers---this converts a $\sqrt n$ scale into a
$\sqrt K$ scale.

\textbf{Sharpness.} The constant $1/4$ enters at exactly one place, the
interpolation lemma, where it is optimal by Proposition~\ref{prop:opt}; the other
loss, $\theta(2-\theta)\le1$, is tight at $\theta=1$.

\textbf{Generality and limitations.} Nothing requires identically distributed
coordinates or structure on the alphabet beyond finiteness. Finiteness of $A$ is
used for compactness in the duality section. Extension to general product
probability spaces follows the same induction once the hull is replaced by a
suitable closure; dependent variables lie outside the scope, where martingale or
transportation methods are the natural substitutes.

\section{Future directions}

\begin{enumerate}
\item Extend the induction beyond product measures, e.g.\ to measures satisfying
a Dobrushin-type contraction condition with a controlled loss per coordinate.
\item Refine the certifiable bound for functionals with certificates of varying
size, averaging over certificate sizes to obtain a mixed exponent.
\item Convert the product-form bounds into moment inequalities for
$|f-\operatorname{med} f|^q$ and two-sided tails with explicit constants.
\item Develop the applications catalogue: random travelling salesman tours,
subgraph counts, first-passage percolation, empirical processes, randomised
algorithms.
\item Replace the finite alphabet by a Polish space, checking that attainment and
the variational inequality survive.
\item Determine the exact optimal constant in the certifiable-functional bound;
the inherited factor $4$ need not be optimal at the certificate scale.
\end{enumerate}

\section*{Summary of results}

\begin{center}
\begin{tabular}{ll}
\toprule
Result & Statement\\
\midrule
Convex distance inequality & $\EE[e^{\dT^2(A,X)/4}]\PP(A)\le1$\\
Deviation bound & $\dT^2\ge t$ on $S$ $\Rightarrow$ $\PP(A)\PP(S)\le e^{-t/4}$\\
Weighted Hamming form & $d_w\ge t$ on $S$ $\Rightarrow$ $\PP(A)\PP(S)\le e^{-t^2/4}$\\
Lipschitz concentration & $\PP(A)\PP(S)\le e^{-t^2/4}$; median form $\le2e^{-t^2/4}$\\
Isoperimetry & $\PP(A)\ge\frac12$ $\Rightarrow$ $\PP(\dT^2\ge t)\le2e^{-t/4}$\\
Interpolation lemma & $e^{(1-\lambda)^2/4}r^{-\lambda}\le2-r$, $\lambda=1+2\log r$\\
Weighted H\"older & $\sum q_if_i^\lambda g_i^{1-\lambda}\le F^\lambda G^{1-\lambda}$\\
Mixing step & $\dT^2(A,(a,y))\le(1-\lambda)^2+\lambda \dT^2(A_a,y)+(1-\lambda)\dT^2(\Pi A,y)$\\
Minimax identity & $\dT(A,x)=\sup\{d_w(A,x):w\ge0,\|w\|_2\le1\}$\\
Singleton & $\dT^2(\{y\},x)=\#\{i:x_i\neq y_i\}$\\
Subcube & $\dT^2(\Cyl(B,c),x)=\#\{i\in B:x_i\neq c_i\}$\\
Certifiable functionals & $\PP(A)\PP(S)\le e^{-(m-b)^2/(4K)}$\\
Counting ones & $\PP(N\le b)\PP(N\ge m)\le e^{-(m-b)^2/(4\lceil m\rceil)}$\\
Longest increasing subsequence & $\PP(L\le b)\PP(L\ge\ell)\le e^{-(\ell-b)^2/(4\lceil\ell\rceil)}$\\
\bottomrule
\end{tabular}
\end{center}

