function optimal_lambda(r, c):
  if r <= 0: return 0
  u <- -log r
  return clamp(1 - u/(2c), 0, 1)

function interpolation_value(r, c):
  lam <- optimal_lambda(r, c)
  value <- exp(c (1-lam)^2) * r^(-lam)
  return (lam, value, (2-r) - value)

function scan(c):
  worst <- +infinity
  for k = 0 .. decades*per_decade:            (logarithmic grid in u)
     u <- 0.5 * 10^(-k/per_decade) ; r <- exp(-u)
     slack <- interpolation_value(r, c).slack
     worst <- min(worst, slack)
  return worst           (>= 0 iff c <= 1/4)

function certificate_bound(m, b, K): return exp(-(m-b)^2/(4K))

function ones_certificate(x, m):
  J <- first ceil(m) indices i with x_i = 1
  return J          (any y agreeing with x on J has at least ceil(m) ones)

function lis_certificate(x, l):
  best[j] <- 1 ; prev[j] <- -1 for all j
  for j = 0..n-1: for i < j: if x_i <= x_j and best[i]+1 > best[j]:
        best[j] <- best[i]+1 ; prev[j] <- i
  follow prev from argmax best to recover a witnessing chain
  return first ceil(l) indices of the chain

function check_certificate(f, x, J, m, alphabet):
  repeat many times: draw y uniformly, overwrite y_i <- x_i for i in J
     if f(y) < m: return false
  return true
